XLV","companyName":"Health Care Select Sector SPDR Fund","category":"sector_etf","merPct":0.09},{"ticker":"XLF","companyName":"Financial Select Sector SPDR Fund","category":"sector_etf","merPct":0.09},{"ticker":"XLY","companyName":"Consumer Discretionary Select Sector SPDR Fund","category":"sector_etf","merPct":0.09},{"ticker":"XLU","companyName":"Utilities Select Sector SPDR Fund","category":"sector_etf","merPct":0.09},{"ticker":"O","companyName":"Realty Income","category":"reit","merPct":null},{"ticker":"PLD","companyName":"Prologis","category":"reit","merPct":null},{"ticker":"AMT","companyName":"American Tower","category":"reit","merPct":null},{"ticker":"AAPL","companyName":"Apple","category":"large_cap","merPct":null},{"ticker":"MSFT","companyName":"Microsoft","category":"large_cap","merPct":null},{"ticker":"GOOGL","companyName":"Alphabet","category":"large_cap","merPct":null},{"ticker":"AMZN","companyName":"Amazon","category":"large_cap","merPct":null},{"ticker":"NVDA","companyName":"NVIDIA","category":"large_cap","merPct":null},{"ticker":"JNJ","companyName":"Johnson & Johnson","category":"large_cap","merPct":null},{"ticker":"PG","companyName":"Procter & Gamble","category":"large_cap","merPct":null},{"ticker":"KO","companyName":"Coca-Cola","category":"large_cap","merPct":null},{"ticker":"PEP","companyName":"PepsiCo","category":"large_cap","merPct":null},{"ticker":"JPM","companyName":"JPMorgan Chase","category":"large_cap","merPct":null},{"ticker":"V","companyName":"Visa","category":"large_cap","merPct":null},{"ticker":"WMT","companyName":"Walmart","category":"large_cap","merPct":null},{"ticker":"COST","companyName":"Costco","category":"large_cap","merPct":null},{"ticker":"UNH","companyName":"UnitedHealth Group","category":"large_cap","merPct":null},{"ticker":"HD","companyName":"Home Depot","category":"large_cap","merPct":null},{"ticker":"MRK","companyName":"Merck","category":"large_cap","merPct":null},{"ticker":"ABBV","companyName":"AbbVie","category":"large_ca